"""Helpers to build QUIC-ish inputs for the offline audit."""
import json, subprocess, sys, hashlib

CLASSES = '/workspace/tmp/classes'

def varint(v):
    if v < 64: return bytes([v])
    if v < 16384: return b'\x40' + v.to_bytes(2,'big')
    if v < 2**30: return b'\x80' + v.to_bytes(4,'big')
    return b'\xc0' + v.to_bytes(8,'big')

def long_header(level, dcid, scid, pn, payload, token=b'', pnlen=4):
    first = (0xc0 if level=='I' else 0xe0) | (pnlen-1)
    out = bytes([first]) + b'\x00\x00\x00\x01'
    out += bytes([len(dcid)]) + dcid + bytes([len(scid)]) + scid
    if level=='I':
        out += varint(len(token)) + token
    out += varint(pnlen+len(payload))
    out += pn.to_bytes(pnlen,'big')
    out += payload
    return out

def short_header(dcid, pn, payload, keyphase=0, pnlen=1):
    first = 0x40 | (keyphase<<2) | (pnlen-1)
    return bytes([first]) + dcid + pn.to_bytes(pnlen,'big') + payload

def trace(events, received=None, limits=None, local=None, peer=None):
    received = received or {'I':None,'H':None,'A':None}
    limits = limits or {'connection':2**62-1,'stream':2**62-1,'bidi':2**60,'uni':2**60,'cids':4}
    local = local or {'bidi':2,'uni':2,'cids':['aa','bb']}
    peer = peer or {'cid':'cc','token':'00'*16}
    return {'limits':limits,'local':local,'peer':peer,'received':received,'events':events}

def dg(wire, auth=None):
    return {'datagram':{'wire':wire.hex() if isinstance(wire,(bytes,bytearray)) else wire,'auth':auth or []}}

def keys(*ks):
    return {'keys':list(ks)}

def run(traces):
    payload = json.dumps({'traces':traces})
    p = subprocess.run([sys.executable,'/workspace/run.py',CLASSES],input=payload.encode(),capture_output=True)
    if p.returncode != 0:
        raise AssertionError('exit %d: %s' % (p.returncode, p.stderr.decode()[:2000]))
    return json.loads(p.stdout)

def sha(b): return hashlib.sha256(b).hexdigest()
